const routes={explore:'Học liệu',library:'Thư viện 3D',lab:'Phòng thí nghiệm Sinh học ảo',studio:'Xưởng khám phá',world:'Thế giới sống',quests:'BioQuest',journey:'Hành trình học',notebook:'Sổ tay của tôi'};
const subpages={lab:['stations','microscope','division','human'],world:['stories','map','careers'],studio:['scale','gene','immune','history','field']};
export function createNavigation({beforeNavigate=()=>{},onNavigate=()=>{}}={}){
 let current=null,lastHash=null;
 function parse(value){let [page,subpage]=value.replace(/^#\/?/,'').split('/');page||='explore';if(page==='collection')page='library';if(page==='microscope'){page='lab';subpage='microscope'}if(!routes[page])page='explore';if(!subpages[page]?.includes(subpage))subpage=undefined;return {page,subpage}}
 function apply({initial=false}={}){if(location.hash===lastHash)return;const {page,subpage}=parse(location.hash),canonical=`#/${page}${subpage?'/'+subpage:''}`;if(location.hash!==canonical)history.replaceState(null,'',canonical);lastHash=location.hash;const changed=current!==page;beforeNavigate(page);current=page;
 document.querySelectorAll('.site-page[data-page]').forEach(el=>{el.hidden=el.dataset.page!==page});document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===page;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});document.body.dataset.page=page;document.title=`${routes[page]} — VNScape`;onNavigate(page,{subpage});
 if(changed&&!initial){window.scrollTo({top:0,behavior:'instant'});document.querySelector(`.site-page[data-page="${page}"] [data-page-heading]`)?.focus({preventScroll:true})}}
 window.addEventListener('hashchange',()=>apply());document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a&&a.getAttribute('href')===location.hash){e.preventDefault();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
 return {start(){apply({initial:true})},navigate(destination){const {page,subpage}=parse(destination),next=`#/${page}${subpage?'/'+subpage:''}`;if(location.hash!==next)location.hash=next;else lastHash=null;apply()},get current(){return current}};
}
